  const MAX_ENTITIES_RENDER_HARD_CAP = 12;
  const FOCUS_STICKINESS = 1.4;

  // ---------- Config: read from JS-Slash-Runner script variables (the editable form in UI) ----------
  // Defaults (used until the user's form values are read). trackChar default = false => user-only mode.
  const CONFIG_DEFAULTS = {
    trackChar: false,
    lang: '',
    showMiniNPCs: true,
    maxNPCs: 6,
  };

  // Live cache: re-read on demand, throttled.
  let _cfgCache = {
    snapshot: '',
    cfg: Object.assign({}, CONFIG_DEFAULTS),
    readAt: 0,
  };
  const CFG_THROTTLE_MS = 500;

  function _normalizeCfg(raw) {
    const r = raw && typeof raw === 'object' ? raw : {};
    const out = Object.assign({}, CONFIG_DEFAULTS);
    if (typeof r.trackChar === 'boolean') out.trackChar = r.trackChar;
    else if (r.trackChar === 'true' || r.trackChar === 1) out.trackChar = true;
    else if (r.trackChar === 'false' || r.trackChar === 0) out.trackChar = false;
    if (r.lang != null) out.lang = String(r.lang).trim().toLowerCase().slice(0, 2);
    if (typeof r.showMiniNPCs === 'boolean') out.showMiniNPCs = r.showMiniNPCs;
    else if (r.showMiniNPCs === 'true' || r.showMiniNPCs === 1) out.showMiniNPCs = true;
    else if (r.showMiniNPCs === 'false' || r.showMiniNPCs === 0) out.showMiniNPCs = false;
    if (r.maxNPCs != null && Number.isFinite(Number(r.maxNPCs))) {
      const n = Math.max(0, Math.min(MAX_ENTITIES_RENDER_HARD_CAP, Math.floor(Number(r.maxNPCs))));
      out.maxNPCs = n;
    }
    return out;
  }

  function _readRawScriptVars() {
    try {
      if (typeof window.getVariables === 'function') {
        const v = window.getVariables({ type: 'script' });
        if (v && typeof v === 'object') return v;
      }
    } catch (_) {}
    try {
      if (window.TavernHelper && typeof window.TavernHelper.getVariables === 'function') {
        const v = window.TavernHelper.getVariables({ type: 'script' });
        if (v && typeof v === 'object') return v;
      }
    } catch (_) {}
    return null;
  }

  /**
   * Read config from script variables. Returns { changed, cfg }.
   * Throttled to once per CFG_THROTTLE_MS, but force=true bypasses throttle.
   */
  function readConfigLive(force) {
    const now = Date.now();
    if (!force && now - _cfgCache.readAt < CFG_THROTTLE_MS) {
      return { changed: false, cfg: _cfgCache.cfg };
    }
    _cfgCache.readAt = now;
    const raw = _readRawScriptVars();
    if (!raw) return { changed: false, cfg: _cfgCache.cfg };
    const cfg = _normalizeCfg(raw);
    const snap = JSON.stringify(cfg);
    if (snap !== _cfgCache.snapshot) {
      _cfgCache.snapshot = snap;
      _cfgCache.cfg = cfg;
      return { changed: true, cfg };
    }
    return { changed: false, cfg };
  }

  function getCfg() {
    // Lazy-read with throttle; ensures fresh value without requiring callers to invoke readConfigLive.
    readConfigLive(false);
    return _cfgCache.cfg;
  }
  function isTrackChar() { return !!getCfg().trackChar; }
  function getForcedLang() {
    const l = (getCfg().lang || '').toString().toLowerCase();
    return l || null;
  }
  function getShowMiniNPCs() { return getCfg().showMiniNPCs !== false; }
  function getMaxNPCs() {
    const n = Number(getCfg().maxNPCs);
    return Number.isFinite(n) ? Math.max(0, Math.min(MAX_ENTITIES_RENDER_HARD_CAP, n)) : CONFIG_DEFAULTS.maxNPCs;
  }

