    'предобморок':{g:'m', adj:{light:'лёгкий', strong:'сильный', extreme:'глубокий'}},
    // Physical neuter (descriptive adjectives, used as predicate state)
    'здоровое':{g:'n_adj'},
    'хорошее':{g:'n_adj'},
    'отличное':{g:'n_adj'},
    'плохое':{g:'n_adj'},
    'тяжёлое':{g:'n_adj'},
    // Physical — masculine (treated as predicate state)
    'ушиб':{g:'m', adj:{light:'небольшой', strong:'сильный', extreme:'обширный'}, plural:'ушибы'},
    // Already-adjective forms (used as predicates, do NOT prepend a separate adjective)
    'ранен':{g:'adj_pred'},
    'в норме':{g:'adj_pred'},
    'без сознания':{g:'adj_pred'},
    'нет признаков жизни':{g:'adj_pred'},
  };

  // Default adjective forms by gender, used when a term has no custom adj table.
  const RU_MOD_ADJ_DEFAULT = {
    light:   {m:'лёгкий',   f:'лёгкая',   n:'лёгкое',   pl:'лёгкие'},
    strong:  {m:'сильный',  f:'сильная',  n:'сильное',  pl:'сильные'},
    extreme: {m:'крайний',  f:'крайняя',  n:'крайнее',  pl:'крайние'},
  };

  // Modifier token -> intensity bucket. The bucket selects the adjective form.
  const RU_MOD_BUCKET = {
    slightly:'light', mildly:'light', somewhat:'light', barely:'light', hardly:'light',
    moderately:'light', quite:'strong', very:'strong', extremely:'extreme',
    // Russian-side modifier tokens (after lookup the canonical RU forms)
    'слегка':'light', 'немного':'light', 'едва':'light',
    'умеренно':'light', 'довольно':'strong', 'очень':'strong', 'крайне':'extreme',
  };
  // Reverse lookup: is this token a known modifier (EN or RU)?
  const RU_IS_MODIFIER = new Set(Object.keys(RU_MOD_BUCKET));

  // Build the natural Russian phrase for a [modifier, term] pair.
  // Returns null if we can't pair them (caller falls back to other strategies).
  function buildRuModPhrase(modifierToken, termRaw) {
    const bucket = RU_MOD_BUCKET[modifierToken];
    if (!bucket) return null;
    const term = (termRaw || '').toString().trim();
    if (!term) return null;
    const meta = RU_TERM_META[term];
    if (meta) {
      // Adjective-predicate term: ignore modifier, just emit the term.
      // (e.g. "ранен", "без сознания" — modifying these reads awkwardly).
      if (meta.g === 'adj_pred') return term;
      // Term comes with a custom adjective table.
      if (meta.adj && meta.adj[bucket]) {
        return meta.adj[bucket] + ' ' + term;
      }
      // Adjective-shaped neuter predicate ("здоровое", "плохое") — modify with adverb.
      if (meta.g === 'n_adj') {
        const adv = {light:'не очень', strong:'весьма', extreme:'крайне'}[bucket] || '';
        return (adv ? adv + ' ' : '') + term;
      }
      // Fallback to default-by-gender adjective.
      const adj = RU_MOD_ADJ_DEFAULT[bucket] && RU_MOD_ADJ_DEFAULT[bucket][meta.g];
      if (adj) return adj + ' ' + term;
    }
    // Unknown term: leave the modifier+term combo to caller (returns null).
    return null;
  }

  // Lookup a single token in the active-language dictionary.
  // Returns translated term, or null if unknown.
  function lookupTerm(token, lang) {
    if (!token) return null;
    const k = token.toLowerCase();
    const map = lang === 'ru' ? TERM_MAP_RU : TERM_MAP_EN;
    if (map[k]) return map[k];
    if (lang === 'ru' && RU_NORMALIZE[k]) return RU_NORMALIZE[k];
    return null;
  }

  // Tokenise a phrase into words, translate each via dictionary, glue back.
  // Used as a fallback when the whole phrase has no entry.
  // For Russian: collapses [modifier + term] pairs into natural adjective+noun
  // phrases via RU_TERM_META (e.g. "mildly anxious" -> "лёгкая тревога").
  // Returns null if NOTHING translates.
  function translatePhraseWordwise(phrase, lang) {
    const tokens = String(phrase).toLowerCase().match(/[\p{L}\p{N}'\u2019-]+/gu);
    if (!tokens || !tokens.length) return null;

    // Step 1: translate each token (modifiers and terms alike); record originals.
    const slots = tokens.map(t => {
      const tr = lookupTerm(t, lang);
      return { raw: t, tr: tr, isMod: RU_IS_MODIFIER.has(t) || (tr && RU_IS_MODIFIER.has(tr)) };
    });

    let hits = slots.filter(s => s.tr).length;
    if (!hits) return null;

    if (lang === 'ru') {
      // Step 2: collapse [modifier, term] adjacent pairs into one natural phrase.
      const out = [];
      for (let i = 0; i < slots.length; i++) {
        const cur = slots[i];
        const next = slots[i + 1];
        // A pair = current is modifier (raw EN or already-translated RU adverb),
        //         AND next has a known translated term that lives in RU_TERM_META.
        if (cur.isMod && next && next.tr && RU_TERM_META[next.tr]) {
          const modKey = cur.raw in RU_MOD_BUCKET ? cur.raw : cur.tr;
          const phrase2 = buildRuModPhrase(modKey, next.tr);
          if (phrase2) {
            out.push(phrase2);
            i++; // consume the next slot
            continue;
          }
        }
        // Dangling modifier without a known partner — drop it instead of emitting
        // raw "slightly" / "слегка" in isolation, which reads as garbage.
        if (cur.isMod && (!next || !next.tr)) continue;
        if (cur.tr) out.push(cur.tr);
        else out.push(cur.raw);
      }
      if (!out.length) return null;
      // Dedupe adjacent duplicates and join.
      const dedup = [];
      for (const w of out) if (dedup[dedup.length - 1] !== w) dedup.push(w);
      return dedup.join(' ');
    }

    // EN path: simple word-by-word stitching (modifiers stay as-is naturally).
    const out = slots.map(s => s.tr || s.raw);
    const dedup = [];
    for (const w of out) if (dedup[dedup.length - 1] !== w) dedup.push(w);
    return dedup.join(' ');
  }

  function humanText(raw, fallback) {
    const s = String(raw == null ? '' : raw).trim();
    if (!s) return fallback || L.normalShort;
    const key = s.toLowerCase();
    const lang = (L === LOCALES.ru) ? 'ru' : 'en';
    // 1) Exact full-phrase match
    const direct = lookupTerm(key, lang);
    if (direct) return direct;
    // 2) Word-wise fallback (handles "mildly anxious", "slightly tense", etc.)
    const wordwise = translatePhraseWordwise(s, lang);
    if (wordwise) return wordwise;
    return s;
  }

  // Split a free-text status into 1-2 short parts via shared separators.
  // Used for both mental.state and physical.condition.
  function splitStateText(value) {
    const s = String(value == null ? '' : value).trim();
    if (!s) return [];
    const compact = s.toLowerCase().replace(/[.;]+/g, ',').replace(/\s+/g, ' ').trim();
    return compact
      .split(/\s*(?:,|\+|\/|\s и \s|\s and \s|\s+но\s+|\s+but\s+)\s*/)
      .map(p => p.trim())
      .filter(Boolean);
  }

  function mentalStateText(value) {
    const parts = splitStateText(value);
    if (!parts.length) return L.normalShort;
    const translated = parts.map(p => humanText(p, '')).filter(Boolean);
    if (!translated.length) return humanText(String(value || ''));
    return Array.from(new Set(translated)).slice(0, 2).join(', ');
  }

  function physicalStateText(value) {
    const parts = splitStateText(value);
    if (!parts.length) return L.normalShort;
    const translated = parts.map(p => humanText(p, '')).filter(Boolean);
    if (!translated.length) return humanText(String(value || ''), L.normalShort);
    return Array.from(new Set(translated)).slice(0, 2).join(', ');
  }

  // ---------- Schema prompt (compact) ----------
  function buildSystemPrompt() {
    const lang = (L === LOCALES.ru) ? 'ru' : 'en';
    const commonRules = `Dimensions: mental (stress/fear/focus/shock/panic/dissociation/morale/delirium/magic), physical (pain/fatigue/mobility/consciousness/bleeding/stamina), wounds, traumas, illnesses, vitals (hr/bp/temp/rr/spo2), needs (sleep/hunger/thirst).

Rules:
