  // ---------- Defaults & numeric utils ----------
  const DEFAULT_ENTITY = {
    name: '?', role: 'npc', present: true,
    overall: 'stable', consciousness: 'alert',
    mental: { state: 'calm', stress: 0, fear: 0, focus: 100, notes: '' },
    physical: { condition: 'fit', pain: 0, fatigue: 0, mobility: 'normal', notes: '' },
    needs: { sleep: 0, hunger: 0, thirst: 0, notes: '' },
    vitals: { hr: 72, bp: '120/80', temp: 36.6, rr: 14, spo2: 98 },
    wounds: [], traumas: [], illnesses: [],
  };

  const GRADE_META = {
    stable: { color: '#22c55e', beat: '1.45s', icon: 'fa-heart-pulse' },
    drowsy: { color: '#a78bfa', beat: '1.65s', icon: 'fa-cloud-moon' },
    sleeping: { color: '#38bdf8', beat: '1.9s', icon: 'fa-moon' },
    strained: { color: '#eab308', beat: '1.05s', icon: 'fa-wave-square' },
    serious: { color: '#f97316', beat: '.78s', icon: 'fa-triangle-exclamation' },
    critical: { color: '#ef4444', beat: '.52s', icon: 'fa-heart-circle-exclamation' },
    deceased: { color: '#ef4444', beat: '1.8s', icon: 'fa-heart-crack' },
  };
  const SEV_SCORE = { mild: 1, moderate: 2, severe: 3, critical: 4 };
  const OVERALL_SCORE = { stable: 0, strained: 1, serious: 2, critical: 3, deceased: 4, dead: 4 };

  function deepClone(obj) {
    if (typeof structuredClone === 'function') {
      try { return structuredClone(obj); } catch (_) {}
    }
    return JSON.parse(JSON.stringify(obj));
  }

  function esc(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function num(value, fallback) {
    fallback = fallback || 0;
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }
  function clamp(value, min, max) { return Math.max(min, Math.min(max, num(value, min))); }
  function decodeHTML(value) {
    return String(value == null ? '' : value)
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
      .replace(/&amp;/g, '&');
  }

  function extractJSON(text) {
    const start = text.indexOf('{');
    if (start < 0) return null;
    let depth = 0, inString = false, escaped = false;
    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (escaped) { escaped = false; continue; }
      if (ch === '\\') { escaped = true; continue; }
      if (ch === '"') { inString = !inString; continue; }
      if (inString) continue;
      if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) return text.slice(start, i + 1); }
    }
    return null;
  }

  // Names that mean "no real entry" — model sometimes fills the schema with placeholders.
  const EMPTY_NAME_RE = /^\s*[?\-–—.…\u2014\u2013]*\s*$/;
  function isMeaningfulConditionName(name) {
    if (name == null) return false;
    const s = String(name).trim().toLowerCase();
    if (!s) return false;
    if (EMPTY_NAME_RE.test(s)) return false;
    if (s === 'none' || s === 'n/a' || s === 'na' || s === 'null' || s === 'undefined') return false;
    if (s === 'нет' || s === 'отсутствует' || s === 'нету' || s === 'не указано' || s === 'неизвестно') return false;
    if (s === 'unknown' || s === 'unspecified' || s === 'tbd') return false;
    return true;
  }
  function normalizeList(value) {
    if (!Array.isArray(value)) return [];
    return value.filter(item => {
      if (!item || typeof item !== 'object') return false;
      // Drop placeholder/empty entries — model occasionally fills schema with blanks.
      return isMeaningfulConditionName(item.name);
    });
  }

  function normalizeEntity(value, fallbackName, fallbackRole) {
    const raw = value && typeof value === 'object' ? value : {};
    const e = deepClone(DEFAULT_ENTITY);
    e.name = String(raw.name || fallbackName || e.name);
    e.role = String(raw.role || fallbackRole || e.role).toLowerCase();
    e.present = raw.present === undefined ? true : Boolean(raw.present);
    e.overall = String(raw.overall || e.overall).toLowerCase();
    e.consciousness = String(raw.consciousness || e.consciousness);
    e.mental = Object.assign({}, e.mental, raw.mental && typeof raw.mental === 'object' ? raw.mental : {});
    e.physical = Object.assign({}, e.physical, raw.physical && typeof raw.physical === 'object' ? raw.physical : {});
    e.needs = Object.assign({}, e.needs, raw.needs && typeof raw.needs === 'object' ? raw.needs : {});
    e.vitals = Object.assign({}, e.vitals, raw.vitals && typeof raw.vitals === 'object' ? raw.vitals : {});
    e.wounds = normalizeList(raw.wounds);
    e.traumas = normalizeList(raw.traumas);
    e.illnesses = normalizeList(raw.illnesses);
    e.mental.stress = clamp(e.mental.stress, 0, 100);
    e.mental.fear = clamp(e.mental.fear, 0, 100);
    e.mental.focus = clamp(e.mental.focus, 0, 100);
    e.physical.pain = clamp(e.physical.pain, 0, 100);
    e.physical.fatigue = clamp(e.physical.fatigue, 0, 100);
    e.needs.sleep = clamp(e.needs.sleep, 0, 100);
    e.needs.hunger = clamp(e.needs.hunger, 0, 100);
    e.needs.thirst = clamp(e.needs.thirst, 0, 100);
    e.vitals.hr = Math.round(clamp(e.vitals.hr, 0, 240));
    e.vitals.temp = Math.round(clamp(e.vitals.temp, 30, 45) * 10) / 10;
    e.vitals.rr = Math.round(clamp(e.vitals.rr, 0, 60));
    e.vitals.spo2 = Math.round(clamp(e.vitals.spo2, 0, 100));
    return e;
  }

  // ---------- Entity validation: roles whitelist + name blacklist ----------
  const VALID_ROLES = new Set([
    'user', 'ally', 'enemy', 'npc', 'neutral',
    'companion', 'stranger', 'friend', 'foe',
    'beast', 'pet', 'familiar', 'summon', 'spirit',
  ]);
  const LOCATION_RE_EN = /\b(world|realm|kingdom|empire|city|town|village|land|continent|universe|setting|location|place|region|faction|guild|party|group|council|order|clan|nation|country|district|temple|castle|tower|fortress|forest|mountain|sea|ocean|river|island|dimension|plane)\b/i;
  const LOCATION_RE_RU = /(^|[\s\-_.,])(мир|сеттинг|королевство|империя|город|деревня|континент|локация|место|фракция|гильдия|отряд|орден|клан|вселенная|нация|страна|храм|замок|башня|крепость|лес|гора|море|океан|река|остров|измерение|план|поселение|село)([\s\-_.,!?:;]|$)/iu;

  function isLocationLikeName(name, key) {
    const s = String(name || key || '').trim();
    if (!s) return false;
    if (LOCATION_RE_EN.test(s)) return true;
    if (LOCATION_RE_RU.test(s)) return true;
    return false;
  }

  function isValidEntity(key, entity, dropped) {
    const role = String(entity && entity.role || '').toLowerCase();
    // User key always wins
    if (key === '{{user}}' || role === 'user') return true;
    if (!VALID_ROLES.has(role)) {
      dropped.push(`${key} (invalid role: ${role || '<empty>'})`);
      return false;
    }
    if (isLocationLikeName(entity && entity.name, key)) {
      dropped.push(`${key} (location-like name)`);
      return false;
    }
    return true;
  }

  // ---------- State parsing (supports both legacy and new schemas) ----------
  function parseState(rawJson) {
    try {
      const data = JSON.parse(decodeHTML(rawJson).trim());
      const out = { scene_effect: String(data.scene_effect || ''), entities: {}, focus: [], _dropped: [] };

      if (data.entities && typeof data.entities === 'object') {
        for (const key of Object.keys(data.entities)) {
          const raw = data.entities[key];
          const role = raw && raw.role;
          const normalized = normalizeEntity(raw, key, role);
          // Validation: drop locations, settings, organizations, invalid roles.
          if (!isValidEntity(key, normalized, out._dropped)) continue;
          out.entities[key] = normalized;
        }
        if (Array.isArray(data.focus)) {
          out.focus = data.focus.map(String).filter(k => out.entities[k]);
        }
      } else {
        // legacy: user + char
        if (data.user) {
          const u = normalizeEntity(data.user, '{{user}}', 'user');
          out.entities['{{user}}'] = u;
        }
        if (isTrackChar() && data.char) {
          const c = normalizeEntity(data.char, '{{char}}', 'ally');
          if (isValidEntity('{{char}}', c, out._dropped)) {
            out.entities['{{char}}'] = c;
          }
        }
      }

      // User-Only mode: strip everything except user, regardless of incoming schema.
      if (!isTrackChar()) {
        const keep = {};
        for (const key of Object.keys(out.entities)) {
          const ent = out.entities[key];
          if (ent && (ent.role === 'user' || key === '{{user}}')) {
            keep[key] = ent;
          }
        }
        out.entities = keep;
        out.focus = [];
      }

      if (out._dropped.length) {
        console.info('[Vitalis] dropped entities:', out._dropped);
      }
      if (!Object.keys(out.entities).length) return null;
      return out;
    } catch (_) { return null; }
  }

  function findAllBlocks(text) {
    if (!text) return [];
    const blocks = [];
    for (const m of String(text).matchAll(TAG_RE_G)) {
      blocks.push({ raw: m[1], full: m[0] });
    }
    if (!blocks.length) {
      const fallback = extractJSON(decodeHTML(String(text)));
      if (fallback) {
        try {
          const parsed = JSON.parse(fallback);
          const hasEntities = parsed.entities && typeof parsed.entities === 'object'
            && Object.values(parsed.entities).some(e => e && e.vitals && typeof e.vitals.hr === 'number');
          const u = parsed.user;
          const hasUser = u && typeof u === 'object'
            && typeof u.overall === 'string'
            && u.vitals && typeof u.vitals === 'object'
            && typeof u.vitals.hr === 'number'
            && u.mental && typeof u.mental === 'object'
            && typeof u.mental.stress === 'number';
          if (hasEntities || hasUser) blocks.push({ raw: fallback, full: fallback });
        } catch (_) {}
      }
    }
    return blocks;
  }

  // ---------- State cache ----------
  let stateCache = { messageId: -1, state: null };
  function invalidateCache() { stateCache = { messageId: -1, state: null }; }

  function findLatestState() {
    if (!window.TavernHelper) return null;
    const TH = window.TavernHelper;
    const last = TH.getLastMessageId();
    if (last < 0) return null;
    if (stateCache.messageId === last && stateCache.state) return stateCache.state;

    // walk back from latest, stop at first valid block
    let start = stateCache.messageId >= 0 ? stateCache.messageId : 0;
    // re-scan from end down to start to find newest
    const range = `0-${last}`;
    const messages = TH.getChatMessages(range);
    if (!Array.isArray(messages) || !messages.length) return stateCache.state || null;
    for (let i = messages.length - 1; i >= 0; i--) {
      const msg = messages[i];
      if (!msg || !msg.message) continue;
      const blocks = findAllBlocks(msg.message);
      for (let j = blocks.length - 1; j >= 0; j--) {
        const s = parseState(blocks[j].raw);
        if (s) {
          stateCache = { messageId: last, state: s };
          return s;
        }
      }
    }
    return null;
  }

  // ---------- Scoring & detection ----------
  function maxConditionSeverity(items) {
    return normalizeList(items).reduce((score, it) => {
      const k = String(it.severity || '').toLowerCase();
      return Math.max(score, SEV_SCORE[k] || 0);
    }, 0);
  }

  function isDeceased(entity) {
    const v = entity.vitals || {};
    const hr = num(v.hr, 72), rr = num(v.rr, 14), spo2 = num(v.spo2, 98);
    const bp = String(v.bp || '').trim();
    const status = [
      entity.overall, entity.consciousness, entity.mental && entity.mental.state,
      entity.physical && entity.physical.condition, entity.physical && entity.physical.mobility,
      entity.physical && entity.physical.notes,
    ].map(x => String(x || '').toLowerCase()).join(' ');
    if (/\b(deceased|dead|corpse|no signs of life)\b/.test(status)) return true;
    if (/(^|[\s,.;:!?])(мертв|мёртв|мертва|мёртвая|мертвое|мёртвое|погиб|погибла|погибший|погибшая|труп|бездыханн|нет признаков жизни)([\s,.;:!?]|$)/i.test(status)) return true;
    if (hr <= 0 && rr <= 0) return true;
    if (hr <= 0 && bp === '0/0') return true;
    if (hr <= 0 && spo2 <= 0) return true;
    return false;
  }

  function isSleeping(entity) {
    if (isDeceased(entity)) return false;
    var con = String(entity.consciousness || '').toLowerCase().trim();
    if (con === 'alert') return false;
    const status = [
      con, entity.mental && entity.mental.state,
      entity.physical && entity.physical.condition,
    ].map(x => String(x || '').toLowerCase()).join(' ');
    if (/\b(asleep|sleeping|sleep)\b/.test(status)) return true;
    if (/(^|[\s,.;:!?])(спит|сон|засыпает)([\s,.;:!?]|$)/i.test(status)) return true;
    return false;
  }

  function isDrowsy(entity) {
    if (isDeceased(entity) || isSleeping(entity)) return false;
    var con = String(entity.consciousness || '').toLowerCase().trim();
    if (con === 'alert') return false;
    const status = [
      con, entity.mental && entity.mental.state,
      entity.physical && entity.physical.condition,
    ].map(x => String(x || '').toLowerCase()).join(' ');
    if (/\b(drowsy|dozing)\b/.test(status)) return true;
    if (/(^|[\s,.;:!?])(сонный|сонная|сонное|сонливость|дремлет|дремота|дремлющий|дремлющая|засыпающий|засыпающая)([\s,.;:!?]|$)/i.test(status)) return true;
    return false;
  }

  // Heuristic score (sanity-check). Returns 0..3.
  function heuristicScore(entity) {
    if (isDeceased(entity)) return 3;
    const v = entity.vitals || {};
    const hr = num(v.hr, 72), temp = num(v.temp, 36.6), rr = num(v.rr, 14), spo2 = num(v.spo2, 98);
    const pain = num(entity.physical && entity.physical.pain, 0);
    const fatigue = num(entity.physical && entity.physical.fatigue, 0);
    const stress = num(entity.mental && entity.mental.stress, 0);
    const fear = num(entity.mental && entity.mental.fear, 0);
    const sleep = num(entity.needs && entity.needs.sleep, 0);
    const hunger = num(entity.needs && entity.needs.hunger, 0);
    const thirst = num(entity.needs && entity.needs.thirst, 0);
    const mobility = String((entity.physical && entity.physical.mobility) || '').toLowerCase();
    const sleeping = isSleeping(entity);
    let score = 0;
    if (pain >= 35 || fatigue >= 55 || stress >= 55 || fear >= 60) score = Math.max(score, 1);
    if (pain >= 65 || fatigue >= 75 || stress >= 75 || fear >= 80) score = Math.max(score, 2);
    if (pain >= 85 || fatigue >= 92) score = Math.max(score, 3);
    if (!sleeping && String(entity.consciousness || '').toLowerCase().includes('unconscious')) score = Math.max(score, 3);
    if (thirst >= 45 || sleep >= 65 || hunger >= 70) score = Math.max(score, 1);
    if (thirst >= 72 || (sleep >= 90 && fatigue >= 70) || hunger >= 92) score = Math.max(score, 2);
    if (thirst >= 88) score = Math.max(score, 3);
    if (hr > 110 || hr < 55 || temp >= 37.8 || rr > 22 || spo2 < 95) score = Math.max(score, 1);
    if (hr > 130 || hr < 45 || temp >= 39 || rr > 28 || spo2 < 92 || mobility.includes('immobile')) score = Math.max(score, 2);
    if (hr > 160 || hr < 35 || temp >= 40.5 || rr > 36 || spo2 < 88) score = Math.max(score, 3);
    score = Math.max(score, Math.min(3, maxConditionSeverity(entity.wounds) - 1));
    score = Math.max(score, Math.min(3, maxConditionSeverity(entity.traumas) - 1));
    score = Math.max(score, Math.min(3, maxConditionSeverity(entity.illnesses) - 1));
    return Math.max(0, Math.min(3, score));
  }

  function gradeName(score) {
    return ['stable', 'strained', 'serious', 'critical', 'deceased'][score] || 'stable';
  }

  function entityGrade(entity) {
    if (isDeceased(entity)) return 'deceased';
    // Trust model's declared overall, sanity-check with heuristic
    const declared = OVERALL_SCORE[String(entity.overall || '').toLowerCase()] || 0;
    const heur = heuristicScore(entity);
    const score = Math.max(declared, heur); // only escalate, never demote
    if (score > 0) return gradeName(score);
    if (isSleeping(entity)) return 'sleeping';
    if (isDrowsy(entity)) return 'drowsy';
    return 'stable';
  }

  function presentEntities(state) {
    return Object.keys(state.entities)
      .map(k => ({ key: k, e: state.entities[k] }))
      .filter(x => x.e && x.e.present !== false);
  }

  function overallGrade(state) {
    const present = presentEntities(state);
    let maxScore = 0;
    for (const x of present) {
      maxScore = Math.max(maxScore, OVERALL_SCORE[entityGrade(x.e)] || 0);
    }
    if (maxScore > 0) return gradeName(maxScore);
    if (present.length && present.every(x => isSleeping(x.e))) return 'sleeping';
    if (present.length && present.some(x => isDrowsy(x.e)) && present.every(x => isSleeping(x.e) || isDrowsy(x.e) || heuristicScore(x.e) === 0)) return 'drowsy';
    return 'stable';
  }

  // ---------- Focus detection ----------
  // Returns ordered keys of NPC entities (user is NEVER part of focus).
  let lastFocus = null;
  function detectSceneFocus(state, recentText) {
    const npcs = presentEntities(state).filter(x => x.e.role !== 'user' && x.key !== '{{user}}');
    if (!npcs.length) { lastFocus = null; return []; }
    if (npcs.length === 1) { lastFocus = npcs[0].key; return [npcs[0].key]; }

    const text = String(recentText || '').toLowerCase();

    const scored = npcs.map(({ key, e }) => {
      let score = 0;
      // 1) Model-declared focus (filter out user keys from state.focus implicitly via npcs)
      const focusIdx = state.focus.indexOf(key);
      if (focusIdx === 0) score += 6;
      else if (focusIdx === 1) score += 3;
      else if (focusIdx > 0) score += 1.5;

      // 2) Name mentions in recent text
      const nm = String(e.name || key).toLowerCase().trim();
      if (nm && nm.length >= 2) {
        try {
          const re = new RegExp('(^|[^\\p{L}\\p{N}_])' + nm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![\\p{L}\\p{N}_])', 'giu');
          const matches = text.match(re);
          if (matches) score += Math.min(4, matches.length * 1.2);
        } catch (_) {}
      }

      // 3) Drama factor
      const dramaSev = Math.max(
        maxConditionSeverity(e.wounds),
        maxConditionSeverity(e.traumas),
        maxConditionSeverity(e.illnesses),
      );
      score += dramaSev * 0.6;
      const ov = String(e.overall || '').toLowerCase();
      if (ov === 'critical') score += 2.5;
      else if (ov === 'serious') score += 1.5;
      else if (ov === 'deceased') score += 4;
      else if (ov === 'strained') score += 0.5;

      // 4) Stickiness
      if (lastFocus === key) score += FOCUS_STICKINESS;

      return { key, score };
    });

    scored.sort((a, b) => b.score - a.score);
    lastFocus = scored[0].key;
    return scored.slice(0, 3).map(s => s.key);
  }

  // ---------- UI helpers ----------
  function icon(name, extra) {
    const key = String(name || 'dot').replace(/^fa-/, '');
    return `<i class="${PFX}-icon ${PFX}-i-${esc(key)} ${esc(extra || '')}"></i>`;
  }
  function tone(level) {
    return ({ ok:'#22c55e', warn:'#eab308', bad:'#f97316', crit:'#ef4444' })[level] || '#22c55e';
  }

  function vitalLevel(type, value) {
    if (type === 'hr') {
      const n = num(value, 72);
      if (n > 130 || n < 40) return 'crit';
      if (n > 115 || n < 50) return 'bad';
      if (n > 100 || n < 60) return 'warn';
      return 'ok';
    }
    if (type === 'bp') {
      const m = String(value || '').match(/(\d+)\s*\/\s*(\d+)/);
      if (!m) return 'ok';
      const sys = Number(m[1]), dia = Number(m[2]);
      if (sys >= 180 || dia >= 120 || sys < 70 || dia < 45) return 'crit';
      if (sys >= 140 || dia >= 90 || sys < 85 || dia < 55) return 'bad';
      if (sys >= 130 || dia >= 85 || sys < 95 || dia < 60) return 'warn';
      return 'ok';
    }
    if (type === 'temp') {
      const n = num(value, 36.6);
      if (n >= 40 || n < 34.5) return 'crit';
      if (n >= 39 || n < 35.5) return 'bad';
      if (n >= 37.5 || n < 36) return 'warn';
      return 'ok';
    }
    if (type === 'rr') {
      const n = num(value, 14);
      if (n > 32 || n < 7) return 'crit';
      if (n > 24 || n < 9) return 'bad';
      if (n > 20 || n < 11) return 'warn';
      return 'ok';
    }
    if (type === 'spo2') {
      const n = num(value, 98);
      if (n < 88) return 'crit';
      if (n < 92) return 'bad';
      if (n < 95) return 'warn';
      return 'ok';
    }
    return 'ok';
  }

  function meterLevel(value, lowIsBad, thresholds) {
    const t = thresholds || (lowIsBad ? { warn:30, bad:15, crit:5 } : { warn:45, bad:70, crit:88 });
    if (lowIsBad) {
      if (value <= t.crit) return 'crit';
      if (value <= t.bad) return 'bad';
      if (value <= t.warn) return 'warn';
      return 'ok';
    }
    if (value >= t.crit) return 'crit';
    if (value >= t.bad) return 'bad';
    if (value >= t.warn) return 'warn';
    return 'ok';
  }

  function meter(label, value, iconName, thresholds, lowIsBad) {
    const v = clamp(value, 0, 100);
    const level = meterLevel(v, !!lowIsBad, thresholds && typeof thresholds === 'object' ? thresholds : null);
    return `<div class="${PFX}-meter ${PFX}-level-${level}" style="--tone:${tone(level)}">
      <div class="${PFX}-meter-row"><span>${icon(iconName)}${esc(label)}</span><b>${v}</b></div>
      <div class="${PFX}-bar"><i style="width:${v}%"></i></div>
    </div>`;
  }

  function vitalPill(label, value, unit, type) {
    const level = vitalLevel(type, value);
    return `<span class="${PFX}-pill ${PFX}-level-${level}" style="--tone:${tone(level)}">
      <span class="${PFX}-vital-head"><small>${esc(label)}</small><i></i></span>
      <span class="${PFX}-vital-value"><b>${esc(value)}</b>${unit ? `<em>${esc(unit)}</em>` : ''}</span>
      <span class="${PFX}-vital-track"><span></span></span>
    </span>`;
  }

  function summaryNote(value, fallback) {
    // Length is constrained by CSS line-clamp; only sanitize whitespace here.
    return String(value || fallback || L.normalShort).replace(/\s+/g, ' ').trim();
  }

  function needsSummary(needs) {
    const adj = L.needsAdj, name = L.needsName;
    const arr = [
      { key:'sleep', value: num(needs && needs.sleep, 0), warn:45, strongAt:75, dangerAt:92 },
      { key:'hunger', value: num(needs && needs.hunger, 0), warn:55, strongAt:82, dangerAt:96 },
      { key:'thirst', value: num(needs && needs.thirst, 0), warn:35, strongAt:70, dangerAt:88 },
    ].sort((a, b) => b.value - a.value);
    const top = arr[0];
    if (!top || top.value < top.warn) return L.balance;
    if (top.value < top.strongAt) return `${adj[top.key].light} ${name[top.key]}`;
    if (top.value < top.dangerAt) return `${adj[top.key].strong} ${name[top.key]}`;
    return `${adj[top.key].danger} ${name[top.key]}`;
  }

  function statusDetails(title, state, note, body) {
    return `<details class="${PFX}-status-box">
      <summary>
        <span class="${PFX}-summary-main">${icon('dot')}<b>${esc(title)}</b></span>
        <span class="${PFX}-summary-state">${esc(summaryNote(humanText(state)))}</span>
      </summary>
      <div class="${PFX}-panel-body">
        <small>${esc(note || '')}</small>
        ${body}
      </div>
    </details>`;
  }

  function roleLabel(role) {
    const r = String(role || '').toLowerCase();
    if (r === 'user') return L.user;
    if (r === 'enemy') return L === LOCALES.ru ? 'противник' : 'enemy';
    if (r === 'ally') return L === LOCALES.ru ? 'союзник' : 'ally';
    if (r === 'neutral') return L === LOCALES.ru ? 'нейтр.' : 'neutral';
    return L.char;
  }

  function renderConditionSection(title, items, iconName) {
    const rows = normalizeList(items);
    const worst = rows.reduce((lvl, it) => Math.max(lvl, SEV_SCORE[String(it.severity || '').toLowerCase()] || 0), 0);
    const level = ['ok','ok','warn','bad','crit'][worst] || 'ok';
    const listHtml = rows.length ? `<div class="${PFX}-list">${rows.map(item => {
      const sev = String(item.severity || 'mild').toLowerCase();
      const sevLabel = (L.severity[sev] || sev);
      const notes = [
        item.loc,
        item.bleeding && item.bleeding !== 'none' ? `${L.bleedPrefix}: ${item.bleeding}` : '',
        item.treated ? L.treated : '',
        item.contagious ? L.contagious : '',
        item.notes,
      ].filter(Boolean).join(' | ');
      return `<div class="${PFX}-item ${PFX}-sev-${esc(sev)}">
        <strong>${esc(item.name || '?')}</strong>
        <span>${esc(sevLabel)}</span>
        ${notes ? `<small>${esc(notes)}</small>` : ''}
      </div>`;
    }).join('')}</div>` : `<div class="${PFX}-empty">${esc(L.none)}</div>`;

    return `<details class="${PFX}-condition ${PFX}-level-${level}" style="--tone:${tone(level)}">
      <summary>
        <span>${icon(iconName)}<b>${esc(title)}</b></span>
        <em>${rows.length}</em>
      </summary>
      ${listHtml}
    </details>`;
  }

  function renderVitals(entity) {
    const v = entity.vitals || DEFAULT_ENTITY.vitals;
    return `<div class="${PFX}-vitals">
      ${vitalPill(L.pulse, num(v.hr, 72), L.hrUnit, 'hr')}
      ${vitalPill(L.pressure, v.bp || '120/80', '', 'bp')}
      ${vitalPill(L.temp, num(v.temp, 36.6), L.tempUnit, 'temp')}
      ${vitalPill(L.breath, num(v.rr, 14), L.rrUnit, 'rr')}
      ${vitalPill(L.oxygen, num(v.spo2, 98), L.pctUnit, 'spo2')}
    </div>`;
  }

  function renderEntityHeader(title, entity, gradeLabel) {
    return `<header>
      <div class="${PFX}-beat"><span></span></div>
      <div class="${PFX}-identity">
        <span>${esc(title)}</span>
        <b>${esc(entity.name)}</b>
      </div>
      <mark>${esc(gradeLabel)}</mark>
    </header>`;
  }

  function renderEntity(title, entity) {
    const grade = entityGrade(entity);
    const meta = GRADE_META[grade];
    const dead = isDeceased(entity);
    return `<article class="${PFX}-entity ${PFX}-${grade}" style="--accent:${meta.color};--beat:${meta.beat}">
      ${renderEntityHeader(title, entity, L.grade[grade] || grade)}
      <div class="${PFX}-ekg ${dead ? PFX + '-flatline' : ''}" aria-hidden="true">
        <svg viewBox="0 0 240 34" preserveAspectRatio="none">
          ${dead
            ? '<polyline points="0,17 240,17"></polyline>'
            : '<polyline points="0,17 18,17 25,15 31,17 45,17 51,21 56,5 62,28 69,17 90,17 101,13 114,17 140,17 158,17 165,15 171,17 185,17 191,21 196,5 202,28 209,17 230,17 240,17"></polyline>'}
        </svg>
      </div>
      ${renderVitals(entity)}
      <div class="${PFX}-status-grid">
        ${statusDetails(L.mental, mentalStateText(entity.mental && entity.mental.state),
          entity.mental && entity.mental.notes,
          `${meter(L.stress, entity.mental && entity.mental.stress, 'fa-bolt')}
           ${meter(L.fear, entity.mental && entity.mental.fear, 'fa-eye')}
           ${meter(L.focusMeter, num(entity.mental && entity.mental.focus, 100), 'fa-crosshairs', { warn:30, bad:15, crit:5 }, true)}`)}
        ${statusDetails(L.body, physicalStateText(entity.physical && entity.physical.condition),
          entity.physical && entity.physical.notes,
          `${meter(L.pain, entity.physical && entity.physical.pain, 'fa-bandage')}
           ${meter(L.fatigue, entity.physical && entity.physical.fatigue, 'fa-battery-quarter')}
           <div class="${PFX}-mini"><span>${esc(L.mobility)}: ${esc(humanText(entity.physical && entity.physical.mobility || 'normal'))}</span><span>${esc(L.consciousness)}: ${esc(humanText(entity.consciousness || 'alert'))}</span></div>`)}
        ${statusDetails(L.needs, needsSummary(entity.needs),
          (entity.needs && entity.needs.notes) || L.needsHint,
          `${meter(L.sleep, entity.needs && entity.needs.sleep, 'fa-moon', { warn:65, bad:90, crit:100 })}
           ${meter(L.hunger, entity.needs && entity.needs.hunger, 'fa-utensils', { warn:70, bad:92, crit:100 })}
           ${meter(L.thirst, entity.needs && entity.needs.thirst, 'fa-glass-water', { warn:45, bad:72, crit:88 })}`)}
      </div>
      <div class="${PFX}-sections">
        ${renderConditionSection(L.wounds, entity.wounds, 'fa-kit-medical')}
        ${renderConditionSection(L.traumas, entity.traumas, 'fa-burst')}
        ${renderConditionSection(L.illnesses, entity.illnesses, 'fa-virus')}
      </div>
    </article>`;
  }

  // Pick the most relevant single short label for a mini-card (top issue).
  // Priorities: deceased > critical condition > severe condition > heavy pain > high stress/fear >
  //             bleeding > high need (sleep/hunger/thirst) > overall grade > sleeping.
  // Trim long names so the pill never breaks layout.
  const ISSUE_TEXT_MAX = 28;
  function trimIssue(s) {
    const str = String(s == null ? '' : s).trim();
    if (str.length <= ISSUE_TEXT_MAX) return str;
    return str.slice(0, ISSUE_TEXT_MAX - 1).replace(/[\s,;:.\-]+$/, '') + '…';
  }
  function topIssue(entity) {
    if (isDeceased(entity)) return { level: 'crit', text: L.grade.deceased };
    const worstWound = normalizeList(entity.wounds).reduce((acc, it) => {
      const sev = SEV_SCORE[String(it.severity || '').toLowerCase()] || 0;
      return sev > acc.sev ? { sev, name: it.name || L.wounds, bleeding: it.bleeding } : acc;
    }, { sev: 0, name: '', bleeding: '' });
    const worstTrauma = normalizeList(entity.traumas).reduce((acc, it) => {
      const sev = SEV_SCORE[String(it.severity || '').toLowerCase()] || 0;
      return sev > acc.sev ? { sev, name: it.name || L.traumas } : acc;
    }, { sev: 0, name: '' });
    const worstIll = normalizeList(entity.illnesses).reduce((acc, it) => {
      const sev = SEV_SCORE[String(it.severity || '').toLowerCase()] || 0;
      return sev > acc.sev ? { sev, name: it.name || L.illnesses } : acc;
    }, { sev: 0, name: '' });
    const condSev = Math.max(worstWound.sev, worstTrauma.sev, worstIll.sev);
    const condName = worstWound.sev >= Math.max(worstTrauma.sev, worstIll.sev)
      ? worstWound.name
      : worstTrauma.sev >= worstIll.sev ? worstTrauma.name : worstIll.name;
    if (condSev >= 4) return { level: 'crit', text: trimIssue(condName || L.grade.critical) };
    if (condSev === 3) return { level: 'bad', text: trimIssue(condName || L.grade.serious) };
    const pain = num(entity.physical && entity.physical.pain, 0);
    const stress = num(entity.mental && entity.mental.stress, 0);
    const fear = num(entity.mental && entity.mental.fear, 0);
    if (pain >= 70) return { level: 'bad', text: L.pain };
    if (fear >= 75) return { level: 'bad', text: L.fear };
    if (stress >= 75) return { level: 'bad', text: L.stress };
    if (worstWound.bleeding && worstWound.bleeding !== 'none') {
      return { level: 'warn', text: L.bleedPrefix };
    }
    const sleep = num(entity.needs && entity.needs.sleep, 0);
    const hunger = num(entity.needs && entity.needs.hunger, 0);
    const thirst = num(entity.needs && entity.needs.thirst, 0);
    if (thirst >= 80) return { level: 'warn', text: L.thirst };
    if (hunger >= 85) return { level: 'warn', text: L.hunger };
    if (sleep >= 85) return { level: 'warn', text: L.sleep };
    if (condSev === 2) return { level: 'warn', text: trimIssue(condName || L.grade.strained) };
    if (pain >= 35 || stress >= 50 || fear >= 50) return { level: 'warn', text: L.grade.strained };
    if (isSleeping(entity)) return { level: 'ok', text: L.grade.sleeping };
    return { level: 'ok', text: L.normalShort };
  }

  function renderMini(entity, idx) {
    const grade = entityGrade(entity);
    const meta = GRADE_META[grade];
    const dead = isDeceased(entity);
    const v = entity.vitals || DEFAULT_ENTITY.vitals;
    const issue = topIssue(entity);
    const delay = (Math.min(num(idx, 0), 8) * 60) + 'ms';
    return `<article class="${PFX}-mini-card ${PFX}-${grade}" style="--accent:${meta.color};--beat:${meta.beat};--cascade-delay:${delay}" title="${esc(entity.name)} — ${esc(L.grade[grade] || grade)}">
      <div class="${PFX}-mini-head">
        <div class="${PFX}-mini-beat"><span></span></div>
        <div class="${PFX}-mini-id">
          <b>${esc(entity.name)}</b>
          <small>${esc(roleLabel(entity.role))}</small>
        </div>
        <mark class="${PFX}-mini-grade">${esc(L.grade[grade] || grade)}</mark>
      </div>
      <div class="${PFX}-mini-ekg ${dead ? PFX + '-flatline' : ''}" aria-hidden="true">
        <svg viewBox="0 0 160 22" preserveAspectRatio="none">
          ${dead
            ? '<polyline points="0,11 160,11"></polyline>'
            : '<polyline points="0,11 14,11 19,9 24,11 38,11 43,15 47,3 51,19 56,11 80,11 92,8 105,11 122,11 130,11 135,9 140,11 152,11 160,11"></polyline>'}
        </svg>
      </div>
      <div class="${PFX}-mini-foot">
        <span class="${PFX}-mini-vital" title="${esc(L.pulse)}">${icon('fa-heart-pulse')}<b>${esc(num(v.hr, 72))}</b><em>${esc(L.hrUnit)}</em></span>
        <span class="${PFX}-mini-issue ${PFX}-level-${issue.level}" style="--tone:${tone(issue.level)}" title="${esc(issue.text)}"><i></i><span>${esc(issue.text)}</span></span>
      </div>
    </article>`;
  }

  function buildWidget(state) {
    const grade = overallGrade(state);
    const meta = GRADE_META[grade];

    // User-Only mode: render exactly one card (user) and nothing else.
    if (!isTrackChar()) {
      const userKey = Object.keys(state.entities).find(
        k => state.entities[k].role === 'user' || k === '{{user}}'
      );
      if (!userKey) return '';
      return `<details class="${PFX} ${PFX}-${grade} ${PFX}-single" style="--accent:${meta.color};--beat:${meta.beat}" data-vitalis-root="1">
        <summary class="${PFX}-summary">
          ${icon(meta.icon)}
          <span>${esc(L.title)}</span>
          <b>${esc(L.grade[grade] || grade)}</b>
          <i class="${PFX}-chev"></i>
        </summary>
        <div class="${PFX}-body">
          ${state.scene_effect ? `<div class="${PFX}-effect">${icon('fa-staff-snake')}${esc(state.scene_effect)}</div>` : ''}
          <div class="${PFX}-entities">
            ${renderEntity(L.user, state.entities[userKey])}
          </div>
        </div>
      </details>`;
    }

    // Pool+focus mode: left = user, right = focus[0] (NPC), rest = mini.
    const userKey = Object.keys(state.entities).find(
      k => state.entities[k].role === 'user' || k === '{{user}}'
    );
    const npcKeysAll = Object.keys(state.entities).filter(k => {
      const e = state.entities[k];
      return e && e.present !== false && e.role !== 'user' && k !== '{{user}}';
    });

    const focusKeys = detectSceneFocus(state, state.scene_effect || '');
    const focusKey = focusKeys[0] || npcKeysAll[0] || null;

    const mainKeys = [];
    if (userKey) mainKeys.push(userKey);
    if (focusKey) mainKeys.push(focusKey);

    const showMini = getShowMiniNPCs();
    const maxMini = getMaxNPCs();
    const otherKeys = (showMini && maxMini > 0)
      ? npcKeysAll.filter(k => mainKeys.indexOf(k) === -1).slice(0, maxMini)
      : [];

    const isSolo = mainKeys.length < 2;

    return `<details class="${PFX} ${PFX}-${grade} ${isSolo ? PFX + '-single' : ''}" style="--accent:${meta.color};--beat:${meta.beat}" data-vitalis-root="1">
      <summary class="${PFX}-summary">
        ${icon(meta.icon)}
        <span>${esc(L.title)}</span>
        <b>${esc(L.grade[grade] || grade)}</b>
        <i class="${PFX}-chev"></i>
      </summary>
      <div class="${PFX}-body">
        ${state.scene_effect ? `<div class="${PFX}-effect">${icon('fa-staff-snake')}${esc(state.scene_effect)}</div>` : ''}
        <div class="${PFX}-entities">
          ${mainKeys.map(k => {
            const e = state.entities[k];
            const title = (e.role === 'user' || k === '{{user}}') ? L.user : L.focus;
            return renderEntity(title, e);
          }).join('')}
        </div>
        ${otherKeys.length ? `<div class="${PFX}-others-label"><span>${esc(L.others)}</span></div>
          <div class="${PFX}-mini-list">${otherKeys.map((k, i) => renderMini(state.entities[k], i)).join('')}</div>` : ''}
      </div>
    </details>`;
  }

  // ---------- CSS ----------
  const CSS = `
