  @media (prefers-reduced-motion:reduce){.${PFX}-mini-card{animation:none}}
  @media(max-width:900px){.${PFX}-entities{grid-template-columns:minmax(0,1fr)}}
  @media(max-width:520px){
    .${PFX}-summary{flex-wrap:wrap;gap:6px}
