    .${PFX}-summary>b{order:2;margin-left:0}
    .${PFX}-summary .${PFX}-chev{order:0;margin-left:auto}
    .${PFX}-identity{align-items:flex-start;flex-direction:column;gap:1px}
    .${PFX}-vitals{grid-template-columns:repeat(2,minmax(0,1fr));padding:6px}
    .${PFX}-pill{padding:6px;min-height:52px}
    .${PFX}-pill b{font-size:13px}
    .${PFX}-status-grid,.${PFX}-sections{padding:0 6px 6px}
    .${PFX}-body{padding:6px}
    .${PFX}-entity header{gap:6px;padding:7px}
    /* B2 also on phones: 2-row summary inside status boxes */
    .${PFX}-status-box>summary{grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto;row-gap:2px;column-gap:8px;padding:7px 8px;min-height:auto}
    .${PFX}-summary-main{grid-column:1/2;grid-row:1}
    .${PFX}-status-box>summary::after{grid-column:2/3;grid-row:1;align-self:center}
