    /* Condition rows (Wounds/Traumas/Illnesses): keep flex, compact badge */
    .${PFX}-condition>summary{padding:6px 8px;min-height:auto;gap:6px}
    .${PFX}-condition>summary em{font-size:10.5px;padding:0 6px;min-width:20px;line-height:1.4}
