    .${PFX}-mini-list{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px}
    .${PFX}-mini-card{padding:6px 7px;gap:4px}
    .${PFX}-mini-id b{font-size:11.5px}
    .${PFX}-mini-grade{font-size:8px;padding:1px 5px}
    .${PFX}-mini-vital b{font-size:12px}
