  }
  @media(max-width:360px){
    .${PFX}-vitals{grid-template-columns:repeat(2,minmax(0,1fr))}
    .${PFX}-pill b{font-size:12px}
    .${PFX}-summary-state{font-size:10px}
    .${PFX}-condition>summary em{font-size:10px;padding:0 5px;min-width:18px}
    .${PFX}-mini-list{grid-template-columns:minmax(0,1fr)}
  }
  `;

  function injectStyles() {
    if (!$('#' + PFX + '-css').length) {
      $('head').append(`<style id="${PFX}-css">${CSS}</style>`);
    }
  }

  // ---------- Utility detection (skip injection on dryRun/quiet) ----------
  function isUtilityGeneration(type, option, dryRun) {
    option = option || {};
    return Boolean(
      dryRun ||
      type === 'quiet' || type === 'quietName' || type === 'quietImage' ||
      option.quiet_prompt || option.quietToLoud || option.quietImage || option.quietName
    );
  }

  // ---------- Continuity compression ----------
  function compactEntityForContinuity(e) {
    const out = {
      n: e.name, r: e.role, p: e.present ? 1 : 0,
      o: e.overall, c: e.consciousness,
    };
    if (e.mental) out.m = { s: e.mental.state, st: e.mental.stress, fr: e.mental.fear, fo: e.mental.focus };
    if (e.physical) out.ph = { c: e.physical.condition, pn: e.physical.pain, ft: e.physical.fatigue, mb: e.physical.mobility };
    if (e.needs) out.nd = { sl: e.needs.sleep, hu: e.needs.hunger, th: e.needs.thirst };
    if (e.vitals) out.v = { hr: e.vitals.hr, bp: e.vitals.bp, t: e.vitals.temp, rr: e.vitals.rr, o2: e.vitals.spo2 };
    if (e.wounds && e.wounds.length) out.w = e.wounds.map(w => ({ n:w.name, l:w.loc, s:w.severity, b:w.bleeding, t:w.treated?1:0 }));
    if (e.traumas && e.traumas.length) out.tr = e.traumas.map(w => ({ n:w.name, s:w.severity }));
    if (e.illnesses && e.illnesses.length) out.il = e.illnesses.map(w => ({ n:w.name, s:w.severity, c:w.contagious?1:0 }));
    return out;
  }

  function compactStateForContinuity(state) {
    // User-Only: emit a single user blob, no entities/focus map.
    if (!isTrackChar()) {
      const userKey = Object.keys(state.entities).find(
        k => state.entities[k].role === 'user' || k === '{{user}}'
      );
      if (!userKey) return { u: null };
      return { u: compactEntityForContinuity(state.entities[userKey]) };
    }
    const out = { f: state.focus || [], e: {} };
    for (const k of Object.keys(state.entities)) {
      out.e[k] = compactEntityForContinuity(state.entities[k]);
    }
    return out;
  }

  const CONTINUITY_PROMPT_HEAD_POOL = '[Vitalis continuity. Previous compact pool state (keys: f=focus,e=entities; per-entity: n=name,r=role,p=present,o=overall,c=consciousness,m=mental,ph=physical,nd=needs,v=vitals,w=wounds,tr=traumas,il=illness):\n';
  const CONTINUITY_PROMPT_HEAD_USER = '[Vitalis continuity. Previous compact {{user}} state (key u; per-entity: n=name,o=overall,c=consciousness,m=mental,ph=physical,nd=needs,v=vitals,w=wounds,tr=traumas,il=illness):\n';
  const CONTINUITY_PROMPT_TAIL_POOL = '\nUpdate the next <vital_status> from this state and the latest scene. Preserve all known entities and unresolved conditions; only change what the scene justifies. Reuse the same entity keys.]';
  const CONTINUITY_PROMPT_TAIL_USER = '\nUpdate the next <vital_status> for {{user}} from this state and the latest scene. Preserve unresolved conditions; change only what the scene justifies.]';

  function injectPrompt(type, option, dryRun) {
    if (!window.TavernHelper) return;
    if (isUtilityGeneration(type, option, dryRun)) return;
    const r = readConfigLive();
    if (r.changed) { invalidateCache(); lastFocus = null; }
    refreshLocale();
    const state = findLatestState();
    try {
      window.TavernHelper.injectPrompts(
        [{ id: PROMPT_ID, position: 'in_chat', depth: 0, role: 'system', content: buildSystemPrompt(), should_scan: false }],
        { once: true },
      );
      if (state) {
        const compact = JSON.stringify(compactStateForContinuity(state));
        const trimmed = compact.length > 2200 ? compact.slice(0, 2200) + '...' : compact;
        const head = isTrackChar() ? CONTINUITY_PROMPT_HEAD_POOL : CONTINUITY_PROMPT_HEAD_USER;
        const tail = isTrackChar() ? CONTINUITY_PROMPT_TAIL_POOL : CONTINUITY_PROMPT_TAIL_USER;
        window.TavernHelper.injectPrompts(
          [{ id: PROMPT_ID + '_continuity', position: 'in_chat', depth: 1, role: 'system',
            content: head + trimmed + tail, should_scan: false }],
          { once: true },
        );
      }
    } catch (err) {
      console.warn('[Vitalis] injectPrompt failed', err);
    }
  }

  // ---------- DOM scrub (safer) ----------
  function scrub($target) {
    // 1) hide stray <vital_status> tags (rare; html parser may keep them)
    $target.find('vital_status').hide();

    // 2) walk top-level children, hide blocks that ARE raw vital JSON dumps
    $target.children().each(function () {
      const $el = $(this);
      if ($el.hasClass(PFX) || $el.find('.' + PFX).length) return;
      if ($el.find('[data-iig-instruction], .iig-img-wrap, .iig-generated-image, .iig-error-image').length) return;
      const text = ($el.text() || '').trim();
      if (!text) return;
      if (text.includes('vital_status')) { $el.hide(); return; }
      // Detect raw JSON dump: starts with { contains entities/user vitals AND mental, length not too long
      if (text.length < 4000 && /^[{\[]/.test(text) && /"vitals"/.test(text) && /"mental"/.test(text) &&
          (/"entities"/.test(text) || /"scene_effect"/.test(text))) {
        $el.hide();
      }
    });

    // 3) clean raw <vital_status>...</vital_status> from text nodes only
    const walker = document.createTreeWalker($target[0], NodeFilter.SHOW_TEXT, null);
    const toReplace = [];
    let node;
    while ((node = walker.nextNode())) {
      const t = node.textContent || '';
      if (!/vital_status|&lt;\s*vital_status/i.test(t)) continue;
      const cleaned = t.replace(TAG_RE_G, '');
      if (cleaned !== t) toReplace.push({ node, cleaned });
    }
    for (const { node, cleaned } of toReplace) {
      node.textContent = cleaned;
    }
  }

  // ---------- Message lifecycle ----------
  function updateMessage(messageId) {
    if (!window.TavernHelper) return;
    const $message = $(`.mes[mesid="${messageId}"]`);
    if (!$message.length) return;
    const $text = $message.find('.mes_text').length ? $message.find('.mes_text') : $message;
    const raw = (window.TavernHelper.getChatMessages(messageId) || [])[0];
    const rawMsg = raw && raw.message ? raw.message : '';
    const blocks = findAllBlocks(rawMsg);
    const states = blocks.map(b => parseState(b.raw)).filter(Boolean);
    if (!states.length) { scrub($text); return; }

    $text.find('.' + PFX).remove();
    const latestId = window.TavernHelper.getLastMessageId();
    const expired = latestId - Number(messageId) >= EXPIRE_AFTER;
    if (expired) { scrub($text); return; }

    readConfigLive();
    refreshLocale();
    $text.prepend($(buildWidget(states[0])));
    scrub($text);
  }

  function scanAll() {
    $('.mes').each(function () {
      const id = Number($(this).attr('mesid'));
      if (Number.isFinite(id)) updateMessage(id);
    });
  }

  // ---------- Init / deinit ----------
  const subscriptions = [];
  function subscribe(eventName, handler) {
    if (typeof window.eventOn !== 'function') return;
    window.eventOn(eventName, handler);
    subscriptions.push({ name: eventName, handler });
  }
  function unsubscribeAll() {
    if (typeof window.eventRemoveListener === 'function') {
      for (const s of subscriptions) {
        try { window.eventRemoveListener(s.name, s.handler); } catch (_) {}
      }
    } else if (typeof window.eventOff === 'function') {
      for (const s of subscriptions) {
        try { window.eventOff(s.name, s.handler); } catch (_) {}
      }
    }
    subscriptions.length = 0;
  }

  let _configPollTimer = null;

  function init() {
    if (!window.TavernHelper || !window.tavern_events || typeof window.eventOn !== 'function') {
      setTimeout(init, 200);
      return;
    }
    // Cleanup previous instance if reloaded
    if (window.__vitalis_deinit) {
      try { window.__vitalis_deinit(); } catch (_) {}
    }
    window.__vitalis_inited = true;
    window.__vitalis_deinit = function () {
      unsubscribeAll();
      if (_configPollTimer) { clearInterval(_configPollTimer); _configPollTimer = null; }
      invalidateCache();
      lastFocus = null;
      window.__vitalis_inited = false;
      console.log('[Vitalis] deinit');
    };

    // Seed defaults into the Variable List form on first install (no-op if already set).
    seedConfigDefaults();
    // Read initial config snapshot.
    readConfigLive(true);

    injectStyles();
    refreshLocale();

    const ev = window.tavern_events;
    const onUpdate = id => updateMessage(id);
    const onLater = id => setTimeout(() => updateMessage(id), 0);
    subscribe(ev.CHARACTER_MESSAGE_RENDERED, onUpdate);
    subscribe(ev.USER_MESSAGE_RENDERED, onUpdate);
    subscribe(ev.MESSAGE_UPDATED, onLater);
    subscribe(ev.MESSAGE_EDITED, onLater);
    subscribe(ev.MESSAGE_SWIPED, id => { invalidateCache(); setTimeout(() => updateMessage(id), 0); });
    subscribe(ev.MESSAGE_DELETED, () => { invalidateCache(); setTimeout(scanAll, 0); });
    subscribe(ev.CHAT_CHANGED, () => { invalidateCache(); lastFocus = null; readConfigLive(true); setTimeout(scanAll, 500); });
    subscribe(ev.MORE_MESSAGES_LOADED, scanAll);
    subscribe(ev.GENERATION_AFTER_COMMANDS, injectPrompt);
    subscribe(ev.GENERATION_STARTED, injectPrompt);
    subscribe(ev.MESSAGE_RECEIVED, () => { invalidateCache(); setTimeout(scanAll, 100); });

    // Poll for config changes from the JS-Slash-Runner Variable List UI.
    // There is no event for "user edited script variables" — poll cheaply.
    _configPollTimer = setInterval(function () {
      const r = readConfigLive(true);
      if (r.changed) {
        invalidateCache();
        lastFocus = null;
        refreshLocale();
        scanAll();
      }
    }, 1500);

    scanAll();
    const cfg = getCfg();
    console.log('[Vitalis] ready', {
      trackChar: cfg.trackChar,
      lang: (L === LOCALES.ru ? 'ru' : 'en'),
      showMiniNPCs: cfg.showMiniNPCs,
      maxNPCs: cfg.maxNPCs,
    });
  }

  $(document).ready(init);
})();
